import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"tools/ 清单——全部 117 个文件（维护者手册）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/tool-inventory.md","filePath":"zh/release/tool-inventory.md"}'),r={name:"zh/release/tool-inventory.md"};function a(s,t,i,_,p,l){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="tools-清单——全部-117-个文件-维护者手册" tabindex="-1">tools/ 清单——全部 117 个文件（维护者手册） <a class="header-anchor" href="#tools-清单——全部-117-个文件-维护者手册" aria-label="Permalink to &quot;tools/ 清单——全部 117 个文件（维护者手册）&quot;">​</a></h1><p><code>tools/</code>（117 个文件：95 个 <code>.py</code> + 16 个 <code>.sh</code> + 6 个数据/C 文件）的完整分类。每个文件一行职责，取自文件头。各节合计恰为 117。带守护机制者的深入剖析：<a href="./guard-scripts.html">guard-scripts</a>； 调用它们的构建目标：<a href="./build-reference.html">build-reference</a>。</p><table tabindex="0"><thead><tr><th>板块</th><th>数量</th></tr></thead><tbody><tr><td>1. 构建流水线（shell + tar 打包器）</td><td>17</td></tr><tr><td>2. 源与数据生成器</td><td>12</td></tr><tr><td>3. 字体与 i18n 生成器</td><td>7</td></tr><tr><td>4. 文档与证据生成器</td><td>3</td></tr><tr><td>5. 架构与确定性守护</td><td>6</td></tr><tr><td>6. E2E / 回归套件</td><td>46</td></tr><tr><td>7. 敌意安全对端（p0/p0fix3）</td><td>9</td></tr><tr><td>8. 测试对端服务器</td><td>4</td></tr><tr><td>9. 历史一次性重构</td><td>7</td></tr><tr><td>10. 数据与 C 文件</td><td>6</td></tr></tbody></table><h2 id="_1-构建流水线-17" tabindex="-1">1. 构建流水线（17） <a class="header-anchor" href="#_1-构建流水线-17" aria-label="Permalink to &quot;1. 构建流水线（17）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>build.sh</code></td><td>POSIX 一条命令入口：依赖检测（gcc/ld/nasm/grub-mkimage/xorriso/mformat/mcopy/python3/zip，各自带其 Debian 包）、<code>--install</code> apt 回退、<code>OC_TOOLS</code> 自动发现、目标分派，以及 WP-13 规范 8 可脚本化 API（<code>build_all/build_iso/build_src/build_ota/config_load/config_save/config_get/cache_lookup/cross_compile/cross_toolchain_setup</code>）</td></tr><tr><td><code>build_iso.sh</code></td><td>OCOS 发布 ISO：把双固件 OCBL 对（BIOS stage1+core + UEFI PE）+ 内核 + ocire.elf 经 OCBL ISO 打包器上架；G13 确定性封印委托给打包器 → <code>build/opencube.iso</code></td></tr><tr><td><code>build_ocire_iso.sh</code></td><td>独立 OCIRE 恢复 ISO（OCBL 启动它；扫描器类别 = 携带 <code>/boot/ocire.elf</code> 的卷）→ <code>build/ocire/ocire.iso</code></td></tr><tr><td><code>build_ocse_iso.sh</code></td><td>OCSE 安装介质 ISO：先对 ELF 运行 <code>check_bss.py</code>，上架 <code>/ocse.mrk</code> 标记 + <code>/boot/ocse.elf</code> → <code>build/ocse.iso</code></td></tr><tr><td><code>build_release.sh</code></td><td>一条命令的发布 SOP 第 1–5 步，带门禁：干净 <code>make all</code>（0 警告）→ <code>reproducible-check</code> → BIOS+UEFI 启动横幅门禁（每次运行全新 mktemp 日志，BUG #63 修复）→ 可选 <code>--deep</code> 门禁 → 文档/网站数据；打印三个 SHA256；拒绝已存在的 tag 或错误的 git 身份；不推送任何东西</td></tr><tr><td><code>make_update_pkg.sh</code></td><td>OTA 包：<code>manifest.json</code>（版本 + 文件 + 按归档顺序拼接的载荷体 sha256）+ 内核 + etc + 文档；自 WP05 起无 boot-cfg 成员（OCBL 动态扫描）</td></tr><tr><td><code>make_ocos_tar.py</code></td><td>确定性 OCOS.TAR 安装载荷（boot/opencube.elf + boot/ocire.elf + etc/opencube.conf；ustar、零 mtime、已排序）</td></tr><tr><td><code>make_ab_disk.sh</code></td><td>A/B 更新盘 <code>build/abdisk.img</code>：p1 boot/flags 64M FAT32 + slot A 128M + slot B 128M + data 128M；仅 mtools（无 loop、无 root）；预置 slot A</td></tr><tr><td><code>make_ocire_disk.sh</code></td><td>WP-02 双启动测试盘：hd0 GRUB 双菜单（OCOS 卷 + 恢复条目），hd1 OCIRE 盘（0xEE 影子、无 GPT 头、FAT12：黄金文件 + MANIFEST.TXT SHA-256 + agent + 64 KiB 日志环）</td></tr><tr><td><code>install-toolchain.sh</code></td><td>免 root 工具链：分 3 批下载 Debian .deb（构建工具 / qemu / grub+固件；含依赖约 117 个包）并 <code>dpkg -x</code> 解到 <code>$OC_OPT</code>（默认 <code>$HOME/opt/extract</code>）：nasm 2.16.03、qemu-system-x86 10.0.13（+数据+库）、xorriso 1.5.6、grub-pc-bin/efi-amd64-bin/common、mtools、ovmf、seabios</td></tr><tr><td><code>env-sandbox.sh</code></td><td>面向 extract 布局的 3 行环境：导出 <code>OC_TOOLS=$HOME/opt/extract</code>、PATH、LD_LIBRARY_PATH</td></tr><tr><td><code>oc_cc.sh</code></td><td>内容寻址编译缓存封装：键 = SHA-256（编译器身份 + 参数 + 源哈希 + 来自 <code>-MM</code> 的头文件内容哈希）；命中按字节一致还原 <code>.o</code>+<code>.d</code>（reproducible-check 保持有效）；<code>OC_CACHE_OFF</code> 绕过、<code>OC_CACHE_DIR</code> 迁移、计数器追加到 <code>STATS</code></td></tr><tr><td><code>oc_menuconfig.sh</code></td><td>无依赖的交互式 <code>.config</code> 编辑器（数字=切换，s=保存，q=退出，r=重置）</td></tr><tr><td><code>vendor_ocse.sh</code></td><td>从 tag <code>v1.0.0</code> 重新 vendor OCSE（143 个文件：kernel core/lib/mem/arch、drivers acpi/block/display/i2c/input/pci/time/usb、fs、boot、l1、chinese）</td></tr><tr><td><code>github_release_wp08.sh</code></td><td>WP-08 时代 GitHub Release 助手：推送 commit+tag、经 API（<code>GITHUB_TOKEN</code>）创建带 ISO 资产的 Release</td></tr><tr><td><code>update_website.sh</code></td><td>读 dist 资产 → 写 <code>website/assets/site-data.js</code> + <code>website/update.json</code> + <code>update-v2.json</code>（OTA 清单）；每次发布幂等，无任何手工编辑</td></tr><tr><td><code>sync_wiki.sh</code></td><td>docs/（EN）+ docs/zh/ → GitHub Wiki：zh 规范页名、EN 作为 <code>&lt;Page&gt;-EN.md</code>、语言横幅、按语言改写 <code>[[Wiki-Link]]</code>、剥离资源；约 83 项的 <code>map_page()</code> 表就是契约</td></tr></tbody></table><h2 id="_2-源与数据生成器-12" tabindex="-1">2. 源与数据生成器（12） <a class="header-anchor" href="#_2-源与数据生成器-12" aria-label="Permalink to &quot;2. 源与数据生成器（12）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>gen_userprogs.py</code></td><td>全量再生 <code>userprogs_data.h</code>：目录应用 + 遗留平铺程序 + 跳过 <code>_shared/</code> + <code>libfoo.c</code>→solib；产出字节数组 + <code>OC_USERPROGS[]</code> 注册表（execve 面）；清除孤儿 blob；重名致命（见 <a href="./guard-scripts.html">guard-scripts</a> §4）</td></tr><tr><td><code>build_c_userprog.py</code></td><td>编译一个 C 用户程序并刷新其 blob；模式：<code>exec</code>（user.ld @0x400000）、<code>pie</code>（ET_DYN + PT_INTERP=/lib/ld.so）、<code>pie-foo</code>（+DT_NEEDED libfoo.so）、<code>ld_so</code>（ld_so.ld @0x10000000）；按模式校验 e_type/PT_INTERP</td></tr><tr><td><code>build_solib.py</code></td><td>solib 一条腿：ET_DYN <code>-Wl,-soname,&lt;name&gt;.so</code>，刷新 <code>l1/solib_data.h</code>（<code>solib_libfoo</code>）</td></tr><tr><td><code>embed_userprog.py</code></td><td>编译一个 <code>.asm</code> 用户程序（NASM）并把其字节追加到生成的头文件</td></tr><tr><td><code>embed_grub.py</code></td><td>stage-2 生成器：GRUB boot.img（512 B 副本）+ core.img（grub-mkimage，带盘上 cfg 所需模块 + 内嵌早期配置）→ <code>grub_boot_data.c</code>；内核 ELF 不被内嵌（经 grub.cfg 作 multiboot2 模块）——内核内安装器的载荷</td></tr><tr><td><code>embed_roots.py</code></td><td>把公共 CA 根（ISRG X1/X2、GlobalSign、GTS R1/R4、DigiCert、Baltimore、Amazon、Microsoft、Sectigo E46/R46）作为 DER 数组内嵌进 <code>crypto_roots.h</code></td></tr><tr><td><code>gen_l1svc_ops.py</code></td><td>把 <code>svc_sysapi_l1svc.h</code> 中的内核 <code>L1SVC_*</code> 编号逐字镜像到 <code>ocos/interface/l1svc_ops.h</code>（只追加重编号契约）</td></tr><tr><td><code>gen_svc_api_headers.py</code></td><td>每个服务发一顶 <code>svc_&lt;name&gt;_api.h</code> 伞头文件；幂等，手工迁移的伞头逐字保留</td></tr><tr><td><code>gen_gzip_vectors.py</code></td><td>供内核更新器自测的 gzip/deflate 测试向量（<code>update_test_vectors.h</code>）</td></tr><tr><td><code>make_wdat_table.py</code></td><td>合成但有效的 ACPI WDAT 表，供 QEMU <code>-acpitable</code> 注入，驱动真实的 q35 TCO 寄存器（WDAT 发现的 WP-12 E2E 门禁）</td></tr><tr><td><code>host_keygen_etc.py</code></td><td>在宿主机上生成 RSA-2048 主机/客户端密钥写入 <code>etc.img</code>（n‖d、各 256 B、e=65537），让客户机跳过数分钟的 TCG 密钥生成</td></tr><tr><td><code>ocse_edits.py</code></td><td>每个 OCSE vendored 源编辑的唯一事实来源（E1 OTA API 剥离、E2 GRUB 封装移出、E3 网络栈不 vendor、E4 崩溃管道打桩、E5 ring-3 kill 移除）；绝不手工编辑 vendored 文件</td></tr></tbody></table><h2 id="_3-字体与-i18n-生成器-7" tabindex="-1">3. 字体与 i18n 生成器（7） <a class="header-anchor" href="#_3-字体与-i18n-生成器-7" aria-label="Permalink to &quot;3. 字体与 i18n 生成器（7）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>gen_font.py</code></td><td>8×16 ASCII 0x00–0xFF 位图字体（16 行 × 8 位，位 7 = 最左）→ <code>screen_font_data.c</code>（<code>screen_font8x16[256][16]</code>）</td></tr><tr><td><code>gen_chinese_font.py</code></td><td>来自 GNU Unifont 轮廓的 16×16 GB2312 字体（矩形并集栅格化、upem=64、无抗锯齿）：6763 个汉字（区 16..87）+ 682 个符号 + 区索引 + unicode→GB 映射 → <code>ocse/chinese/chinese_font_data.c</code></td></tr><tr><td><code>gen_font_gz.py</code></td><td>把六张中文字体表包成一个 gzip 块——恒等窗口减压：内核必须结束于 0x400000 之下（用户地址空间让 0x400000–0x600000 留空）；约 298 KiB 的裸 <code>.rodata</code> 变成惰性解压流</td></tr><tr><td><code>gen_l0_i18n.py</code></td><td><code>etc/i18n/l0/{en,zh}.json</code>（各 49 键）→ <code>core_lib_i18n_data.c</code> 中按键排序的查找表，供 <code>l0_tr_()</code> 二分查找</td></tr><tr><td><code>gen_pinyin_phrase.py</code></td><td><code>tools/ime_phrases.txt</code> → 拼音排序的词组表（最长匹配优先）；无声调拼音由内核单字表合成——不用 pypinyin（CI 干净环境修复）</td></tr><tr><td><code>apply_i18n_hints.py</code></td><td>把 <code>_hint</code>（en, zh）对写进每个程序的 <code>i18n/{en,zh}.json</code>——覆盖全部 274 个程序的手写词典</td></tr><tr><td><code>apply_tool_i18n.py</code></td><td>让文件工具应用的用户可见句子过 <code>tr_()</code>（gettext 模型：键 = 英文句子；ZH 键带真实换行——v1 的字面 <code>\\n</code> 键从未匹配上）</td></tr></tbody></table><h2 id="_4-文档与证据生成器-3" tabindex="-1">4. 文档与证据生成器（3） <a class="header-anchor" href="#_4-文档与证据生成器-3" aria-label="Permalink to &quot;4. 文档与证据生成器（3）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>gen_api_docs.py</code></td><td>文档数据生成器：解析运行时 <code>help -a</code> 抓取（注册表头 + <code>name [tag] hint</code> 行；容忍串口回显重叠）或 <code>--qemu</code> 实时抓取 → <code>docs/data/{commands,interfaces,stats}.json</code>；<code>--pages</code>/<code>--pages-zh</code>/<code>--md</code> 再生 292 个命令参考页（EN+ZH）；v1 基线回退 <code>evidence/v1_command_list.txt</code></td></tr><tr><td><code>qemu_shot.py</code></td><td>运行 QEMU → 等待 → screendump → 杀掉（PPM 输出）</td></tr><tr><td><code>qemu_shot_vnc.py</code></td><td>经 PIL 写 PNG 的 VNC 变体——<code>make shot-bios</code> / <code>make shot-uefi</code> 背后的引擎</td></tr></tbody></table><h2 id="_5-架构与确定性守护-6" tabindex="-1">5. 架构与确定性守护（6） <a class="header-anchor" href="#_5-架构与确定性守护-6" aria-label="Permalink to &quot;5. 架构与确定性守护（6）&quot;">​</a></h2><p>每个的深入剖析见 <a href="./guard-scripts.html">guard-scripts</a>。</p><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>check_deps.py</code></td><td><code>ocos/{kernel,drivers,services,l1apps}</code> 上的依赖方向门禁：内核不得 include 驱动/服务（组合根除外）、驱动不得 include 服务、l1apps 只用 <code>ocos/interface/</code> 头；按真实文件清单做纯基名解析；任一违规即 exit 1 带 file:line</td></tr><tr><td><code>check_bss.py</code></td><td>任何常规 <code>.bss</code> 变量不得落入 <code>[__boot_pml4, __ocse_work_start)</code>（页表 + 引导栈）；一个落在活动 PML4 上的 64 KiB 缓冲曾让启动三重故障；接入 <code>build_ocse_iso.sh</code></td></tr><tr><td><code>v2_registry_gate.py</code></td><td>v2 B 组冻结：启动按声明收集的内核，验证命令面（231 行 <code>help -a</code> / 总计 233 / 收集日志 / 服务组视图）</td></tr><tr><td><code>fat_zero_dates.py</code></td><td>把 mtools 镜像中每个 FAT12/16 日期/时间字段清零（mformat/mcopy 盖墙上时钟），使相隔几分钟的两次构建保持字节一致</td></tr><tr><td><code>iso_zero_ctime.py</code></td><td>把每个 ISO9660 目录记录中的 Rock Ridge TF ctime/atime 戳改写为 1970 纪元（xorriso 把 ctime 硬编码为组装时间；atime 泄漏在 WP04-fix1 修复）</td></tr><tr><td><code>fix_file_headers.py</code></td><td>改写指向重构前路径的过期 <code>* File:</code> 头注释（仅注释）</td></tr></tbody></table><h2 id="_6-e2e-回归套件-46" tabindex="-1">6. E2E / 回归套件（46） <a class="header-anchor" href="#_6-e2e-回归套件-46" aria-label="Permalink to &quot;6. E2E / 回归套件（46）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>qemu_runner.py</code></td><td>共享 QEMU+pexpect 驱动：启动 ISO、运行 shell 命令（<code>@</code> 前缀 = 经 <code>mon:stdio</code> 的 HMP monitor）、<code>strip_ansi()</code>、<code>boot_to_recovery()</code>、<code>screen_assert_text()</code>（BUG #66：PPM screendump 必须显示 ≥2 色和可测的前景比例）</td></tr><tr><td><code>run_host_tests.py</code></td><td><code>make test</code> 后端：从每个 <code>tests/host_*.c</code> 头部提取 gcc 行、重映射重构前路径、编译 + 运行；openssl 夹具缺失时 SKIP-FIXTURE</td></tr><tr><td><code>run_fix4_regression.py</code></td><td>31 项检查全量回归门禁（下限机制见 <a href="./ci-gates.html">ci-gates</a> §6）</td></tr><tr><td><code>run_fix4_https_e2e.py</code></td><td>8 项检查 HTTPS E2E 门禁（TLS 1.2 + 0x0067 密码套件、close_notify 记录器、截断防护）</td></tr><tr><td><code>ssh_g11a_e2e.py</code></td><td>5 项检查 SSH E2E 门禁（客户机→宿主 paramiko + 客户机 sshd ← 宿主客户端）</td></tr><tr><td><code>run_l1_per_app.py</code></td><td>P-08 逐应用记录：每个程序启动一次 ISO（每行全新进程表），经 <code>run &lt;name&gt;</code> 运行</td></tr><tr><td><code>run_ocire_tests.py</code></td><td>OCIRE 独立全套：boot/help/unknown/backspace/shutdown × BIOS+UEFI</td></tr><tr><td><code>run_ocire_dual_tests.py</code></td><td>WP-01 双启动 + 分区隔离（GRUB 菜单启动 OCOS 或 OCIRE；0xEE 影子盘不动）</td></tr><tr><td><code>run_ocire_shell_tests.py</code></td><td>WP-02 第 4 组恢复 shell 全套，跑在一次性磁盘副本上（摘要损坏、BPB 被清零的完整修复）</td></tr><tr><td><code>run_ocire_supervised_tests.py</code></td><td>WP-03 G4 OCIRE 监督启动（60 秒看门狗 + 邮箱 + agent）</td></tr><tr><td><code>wp07a_state_e2e.py</code></td><td>启动状态监视门禁：S1 正常阶段 1..6 + 45 秒不复位 + 隔离遍历，S2 user_request → OCIRE，S3 hang_boot 由 30 秒预算诊断，…，S8 OVMF 下 UEFI 冒烟</td></tr><tr><td><code>wp11_crash_e2e.py</code></td><td>崩溃恢复：#DE/#UD/#PF 自测、sigsegv/stackovf/badapp、crashlog 刷到 /var/log、dump + dumpinfo</td></tr><tr><td><code>wp12_watchdog_logging_e2e.py</code></td><td>14 个场景 S1–S14：klog 级别/开关、logcat 过滤器、dmesg 回放、logctl、持久化+轮转 <code>.1</code> 链、全局过滤器、Intel TCO 真实复位 + 第二次启动、ACPI WDAT、策略击杀、健康 JSON</td></tr><tr><td><code>wp10_native_e2e.py</code></td><td>原生桌面流程</td></tr><tr><td><code>wp10_native_manual.py</code></td><td>把抖动检查作为隔离的全新 QEMU 场景重跑（HMP screendump 之后 QEMU 丢串口 RX 字节——经内核内 RX 跟踪验证）</td></tr><tr><td><code>wp10_fix2_render_e2e.py</code></td><td>像素级验证 TUI 汉字渲染——对照内嵌字体位图的完整 16×16 字形</td></tr><tr><td><code>wp10_chinese_shot.py</code></td><td>驱动 font-test/tui-cn、screendump、对照内嵌位图比较 CJK 字形块</td></tr><tr><td><code>wp10_chipset_e2e.py</code></td><td>芯片组/输入命令面：input→expected→actual→verdict 记录（BIOS 或 UEFI）</td></tr><tr><td><code>wp10_timer_rtc_e2e.py</code></td><td>时间源面：CMOS RTC / HPET / ACPI PM 定时器 / TSC</td></tr><tr><td><code>wp10_wireless_bluetooth_e2e.py</code></td><td>无线 + BT 面；BT 是经 COM2 H4 字节进 <code>bt_test_peer.py</code> 的真实 E2E</td></tr><tr><td><code>wp10_camera_misc_e2e.py</code></td><td>UVC 30/30、parallel 10/10（SPP 字节在 chardev 文件中验证）、gameport 6/6、IR 14/14（NEC/RC5/RC6/SIRC）、SCSI 对 LSI 53C895A</td></tr><tr><td><code>wp10_wp08fix1_test.py</code></td><td>行编辑（oc&gt; 和 ush）+ ush 工具 + nano 编辑器；文本走串口、方向键走 HMP sendkey</td></tr><tr><td><code>wp_p2_batch_a_test.py</code></td><td>经 <code>p2test</code> 应用的 A 批次现场探针（read0 #14、管道槽泄漏 #9、…）</td></tr><tr><td><code>test_p1fix3_runtime.py</code></td><td>BUG-0133 <code>umount /</code> 被拒绝、BUG-0134 run/kill tid + 延迟上限、BUG-0135 vi 模态编辑器</td></tr><tr><td><code>tui_g11c_e2e.py</code></td><td>八个全屏 TUI 页：启动、HMP screendump PNG 证据、Esc 离开、提示符回来</td></tr><tr><td><code>ime_g11b_e2e.py</code></td><td>经 PS/2 队列用 HMP sendkey 做 <code>ime -i</code> 组合（&quot;ni&quot; + 数字 1 → 你）</td></tr><tr><td><code>fix1_before_ush.py</code></td><td>WP04-fix1 BEFORE 证据抓取（原始字节 unix-socket 串口通道，控制字节逐字到达）</td></tr><tr><td><code>fix1_before_tui.py</code></td><td>同上，TUI 侧</td></tr><tr><td><code>fix1_after_ush.py</code></td><td>AFTER 证据抓取（ush）</td></tr><tr><td><code>fix1_after_ush2.py</code></td><td>AFTER 证据抓取，第二轮</td></tr><tr><td><code>fix1_checkupdate_e2e.py</code></td><td>出厂 ISO 的 checkupdate 看到真实线上源、诚实的 up-to-date（版本反转回归）</td></tr><tr><td><code>fix1_ocire_kbd_scroll.py</code></td><td>OCIRE PS/2 键盘滚动证明</td></tr><tr><td><code>fix1_ocire_vga_scroll.py</code></td><td>OCIRE VGA 文本滚动证明（0xB8000 单元数组的 pmemsave、冻结带分析、无 OCR）</td></tr><tr><td><code>fix1_ocire_vga_scroll2.py</code></td><td>VGA 滚动证明，第二轮（基于 screendump）</td></tr><tr><td><code>wp01_gui_click_test.py</code></td><td>BUG #113：经 QMP <code>input-send-event</code> 的真实指针点击（按压沿锁存）</td></tr><tr><td><code>wp01_killrace_test.py</code></td><td>BUG #5：kill/fork 竞态压力，每轮之后提示符保持响应</td></tr><tr><td><code>wp01_p0leak_test.py</code></td><td>P0 用户指针栅栏探针（内核地址 sys_write/read 必须被栅栏）</td></tr><tr><td><code>wp01_section_dump.py</code></td><td>差异分诊驱动器：运行一组 ush 命令，逐字转储每一节</td></tr><tr><td><code>wp06g3_baseline.py</code></td><td>编码修复全套：基线抓取</td></tr><tr><td><code>wp06g3_repro_nano_scroll.py</code></td><td>nano 滚动/串口编码复现</td></tr><tr><td><code>wp06g3_repro_serial_enc.py</code></td><td>串口编码复现</td></tr><tr><td><code>wp06g3_test_editor_rework.py</code></td><td>编辑器重做（zh 头图例、IME 预编辑纪律、无滚动渲染）</td></tr><tr><td><code>wp06g3_test_install_ocire.py</code></td><td>带 OCIRE 分区的安装</td></tr><tr><td><code>wp06g3_test_ocire_menu.py</code></td><td>OCBL 菜单 OCIRE 条目</td></tr><tr><td><code>wp06g3_test_ocse_enc.py</code></td><td>OCSE 编码（utf8/gbk）</td></tr><tr><td><code>wp06g3_test_serial_enc.py</code></td><td><code>serial_encoding</code> 命令面</td></tr></tbody></table><h2 id="_7-敌意安全对端-9" tabindex="-1">7. 敌意安全对端（9） <a class="header-anchor" href="#_7-敌意安全对端-9" aria-label="Permalink to &quot;7. 敌意安全对端（9）&quot;">​</a></h2><p>p0/p0fix3 敌意服务器驱动器（P0 安全批次；案例矩阵客户端侧 a04/a05、sshd 侧 a09/a13/a38、TLS a18_chain_*）：</p><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>p0_paramiko_evil.py</code></td><td>BUG-0013 SSH 溢出驱动器（敌意 paramiko 服务器）</td></tr><tr><td><code>p0_evil_tls_server.py</code></td><td>BUG-0022/0023/0024 TLS 记录过读服务器</td></tr><tr><td><code>p0_redir_server.py</code></td><td>BUG-0021 超大重定向路径服务器</td></tr><tr><td><code>p0_run_p0_case.py</code></td><td>p0 案例运行器</td></tr><tr><td><code>p0_run_tls_case.py</code></td><td>p0 TLS 案例运行器</td></tr><tr><td><code>p0fix3_evil_tls.py</code></td><td>chain_buf 回绕（p0fix3 批次）</td></tr><tr><td><code>p0fix3_run_case.py</code></td><td>p0fix3 案例运行器（矩阵含 <code>OC_ETC_IMG</code> 预置主机密钥快速路径）</td></tr><tr><td><code>p0fix3_new01_test.py</code></td><td>首次运行主机密钥生成：非阻塞通知、^C 取消、后台完成、持久化</td></tr><tr><td><code>p0fix3_new01b_test.py</code></td><td>第二次启动快速路径</td></tr></tbody></table><h2 id="_8-测试对端服务器-4" tabindex="-1">8. 测试对端服务器（4） <a class="header-anchor" href="#_8-测试对端服务器-4" aria-label="Permalink to &quot;8. 测试对端服务器（4）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>paramiko_sshd.py</code></td><td>宿主 SSH 服务器：记录协商出的 DH 共享密钥 K（与内核 dhtest 交叉核对）、密码 oc/oc、exec 通道 → /bin/sh</td></tr><tr><td><code>https_test_server.py</code></td><td>与内核客户端匹配的单请求 OpenSSL HTTPS 服务器（仅 TLS 1.2、0x0067 DHE-RSA-AES128-SHA256、1024 位 RFC 3526 DH、自签名；<code>observe</code> 模式 = 原始字节 close_notify 记录器、<code>eof</code> 模式 = 硬关闭截断服务器）</td></tr><tr><td><code>update_server.py</code></td><td>供 checkupdate 测试的更新清单服务器（HTTP 或 TLS）；整个 QEMU 会话期间循环</td></tr><tr><td><code>bt_test_peer.py</code></td><td>COM2 上的 H4 BT 控制器 + 虚拟遥控（L2CAP/SDP/RFCOMM-SPP/HID）</td></tr></tbody></table><h2 id="_9-历史一次性重构-7" tabindex="-1">9. 历史一次性重构（7） <a class="header-anchor" href="#_9-历史一次性重构-7" aria-label="Permalink to &quot;9. 历史一次性重构（7）&quot;">​</a></h2><p>为出处保留；它们硬编码了历史绝对根 （历史上位于本树之外的一份检出），不属于任何当前流水线。</p><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>restructure_move.py</code></td><td>WP-10 project_restructure 阶段 1：按新布局逐项 git-mv</td></tr><tr><td><code>restructure_includes.py</code></td><td>阶段 1b：include 改写</td></tr><tr><td><code>restructure_build_map.py</code></td><td>阶段 2a：符号重命名映射构建</td></tr><tr><td><code>restructure_apply_map.py</code></td><td>阶段 2a-final：映射应用</td></tr><tr><td><code>restructure_rename_iface.py</code></td><td>阶段 2：接口重命名</td></tr><tr><td><code>nak_migrate.py</code></td><td>NAK 重构引擎：旧→新映射、唯一性不变量、<code>git mv</code> + include 改写（映射歧义 / 重复目标 = 失败）</td></tr><tr><td><code>nak_fix_refs.py</code></td><td>NAK 线的移动后引用修复器</td></tr></tbody></table><h2 id="_10-数据与-c-文件-6" tabindex="-1">10. 数据与 C 文件（6） <a class="header-anchor" href="#_10-数据与-c-文件-6" aria-label="Permalink to &quot;10. 数据与 C 文件（6）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>是什么</th></tr></thead><tbody><tr><td><code>host_gzip_test.c</code></td><td>宿主侧 gzip 解压测试程序</td></tr><tr><td><code>ocire_fat_host_test.c</code></td><td>宿主侧 OCIRE FAT 驱动测试</td></tr><tr><td><code>ocse_kmain_c</code></td><td>OCSE kmain.c vendoring 载荷（由 <code>vendor_ocse.sh</code> 复制）</td></tr><tr><td><code>ime_phrases.txt</code></td><td>IME 词组表（词 + 多音字条目的显式拼音）</td></tr><tr><td><code>nak_map.tsv</code></td><td>NAK 重构旧→新映射（77 KB）</td></tr><tr><td><code>update_test_vectors.h</code></td><td>已提交的更新器测试向量（由 <code>gen_gzip_vectors.py</code> 生成）</td></tr></tbody></table><h2 id="_11-新维护者的阅读顺序" tabindex="-1">11. 新维护者的阅读顺序 <a class="header-anchor" href="#_11-新维护者的阅读顺序" aria-label="Permalink to &quot;11. 新维护者的阅读顺序&quot;">​</a></h2><ol><li><code>build.sh</code> + <code>Makefile</code> 头——任何东西是怎么构建的。</li><li><code>build_release.sh</code>——发布是怎么被门禁的（然后是 <a href="./process.html">process</a>、<a href="./ci-gates.html">ci-gates</a>）。</li><li><code>qemu_runner.py</code>——每个套件都假定的共享 E2E 基底。</li><li><code>gen_userprogs.py</code> + <code>gen_api_docs.py</code>——让系统自我描述的 两个注册表（内嵌程序；命令文档）。</li><li>动分层、<code>.bss</code> 布局或确定性之前，先看 <a href="./guard-scripts.html">guard-scripts</a> 里的守护。</li></ol><p>已知清单缺口（已记录，不隐藏）：没有已提交的大应用冒烟脚本 ——WP-l1apps-merge 发布说明引用的 21/21 门禁是一个被引用的 台架；重建它的 Phase A/B 清单在 <code>docs/dev/e2e-suites.md</code>。 <code>oc_menuconfig.sh</code> 的菜单文本仍在宣传已移除的 <code>CONFIG_TUI</code>/<code>CONFIG_CHINESE</code> 旋钮（Makefile 只消费 NVME/AHCI/VIRTIO_BLK）。</p>',29)])])}const b=d(r,[["render",a]]);export{h as __pageData,b as default};
